pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newMinSum) public {
        // Keep MinSum in a wide admissible range
        vm.assume(newMinSum > 0 && newMinSum < type(uint256).max);

        // Step 1: Initialize the contract
        c.Initialized();

        // Step 2: Attempt to call SetMinSum with the fuzzed value.
        // In reference contract, this call reverts because intitalized is true.
        // In buggy contract, it succeeds and changes MinSum.
        try c.SetMinSum(newMinSum) { } catch { }

        // Step 3: Drive through Collect with a zero amount (does not affect MinSum).
        // We need to call Collect so that the property is evaluated after this entry point.
        // Set up an account with some balance to allow Collect to proceed silently.
        address collector = address(0x123);
        vm.deal(collector, 5 ether);
        vm.prank(collector);
        c.Put{value: 3 ether}(0);
        // Warp past unlock time
        vm.warp(block.timestamp + 1);
        vm.prank(collector);
        try c.Collect(1) { } catch { }

        // Assertion: In the reference contract, MinSum remains 0 because SetMinSum reverted.
        // In the buggy contract, SetMinSum succeeded after initialization, so MinSum equals newMinSum.
        // Thus, the property "MinSum is always 0 after any sequence that calls SetMinSum post-initialization and then Collect"
        // holds for reference, but fails for the buggy version.
        assertTrue(c.MinSum() == 0);
    }
}

