pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(uint256 newMinSum, uint256 collectAmt) public {
        // Restrict to sane values that won't overflow and allow Collect to succeed if conditions met
        vm.assume(newMinSum > 0 && collectAmt > 0 && collectAmt <= type(uint128).max);
        vm.assume(collectAmt <= newMinSum);

        // Initialize and set a baseline MinSum
        c.SetMinSum(newMinSum);
        c.Initialized();
        uint256 minSumBefore = c.MinSum();

        // Fund a user, Put + lock expires
        address user = makeAddr("user");
        vm.deal(user, collectAmt);
        vm.startPrank(user);
        c.Put{value: collectAmt}(0);
        vm.stopPrank();
        vm.warp(block.timestamp + 1);

        // Now drive Collect which uses MinSum in its condition
        uint256 minSumAfterCollect;
        bool ok = false;
        vm.prank(user);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {}
        minSumAfterCollect = c.MinSum();

        // Reference invariant: after initialization, MinSum never changes by any Collect call
        // Bug allows SetMinSum after init, so an attacker can call it and break this.
        // But our test only calls Collect; the invariant is: MinSum after Collect equals MinSum before.
        // The bug allows changing MinSum by an external actor, but the fuzz inputs explore whether
        // the normal Collect path itself changes MinSum. Actually, we test: whatever happens (even if
        // someone calls SetMinSum due to the bug), after a Collect call MinSum equals the initial value set before init.
        // To model the bug properly, we need to allow SetMinSum to be called after init in the test.
        // Since the test interacts only through the public surface, the mutant will call SetMinSum after init if we do so.
        // We do NOT call SetMinSum after init in this test; the bug is trivially triggerable but our property is:
        // "After any sequence where only Collect is the state-changing operation after initialization, MinSum remains unchanged."
        // That is true for reference, but the bug may let an unrelated call change it. Not captured.
        // The proper property: MinSum after any Collect call equals the MinSum set before initialization, assuming no other SetMinSum
        // call after init. But the bug allows anyone to call SetMinSum after init, so MinSum can diverge.
        // The fuzzer needs ability to call SetMinSum after init to expose the difference.
        // We'll let the fuzzer choose whether to call SetMinSum after init by providing a boolean flag (not allowed? fuzz params are uint).
        // Instead we use the fuzzed newMinSum value and call SetMinSum after initialization if the fuzzer picks a scenario where it's possible.
        // Actually we just call SetMinSum after init for everyone to see the divergence.
        // The instruction says: "Drive through the public/external entry Collect(uint256), P and M differ in this way: after a call to Collect(...) completes, the value of state variable MinSum differs."
        // So the test MUST include a Collect call and then assert about MinSum.
        // The fuzzed parameters are the inputs that influence whether the difference manifests.
        // We'll have the fuzzer provide a boolean (0/1) as uint256 to decide whether to attempt a SetMinSum after init.
    }
}

