pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint128 value, uint32 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(value > 0);

        // Initialize contract to make Put usable
        c.SetMinSum(0);
        c.SetLogFile(address(0)); // using address(0) won't break logic for the property we check
        c.Initialized();

        // Get balance before
        uint256 contractBalanceBefore = address(c).balance;

        // Perform Put
        vm.deal(actor, value);
        vm.prank(actor);
        c.Put{value: value}(lockTime);

        // Get contract balance after
        uint256 contractBalanceAfter = address(c).balance;

        // Get accumulator balance for actor
        (uint unlockTime, uint accBalance) = c.Acc(actor);

        // The invariant: contract balance must be >= actor's recorded balance.
        // Since only one actor deposits, contract balance should equal accBalance only if there are no other depositors.
        // A stronger invariant: contract balance should be >= sum of all balances; here with one actor, contract balance == accBalance.
        // With overflow, accBalance won't match actual deposited amount.
        bool invariantHolds = (contractBalanceAfter == contractBalanceBefore + value) && (accBalance == value);
        assertTrue(invariantHolds);
    }
}

